#!/usr/bin/env bash
# Generated by scripts/build-diagnostics.py. No credentials are embedded.
set -euo pipefail
export PATH=/usr/sbin:/usr/bin:/sbin:/bin

if [[ $# -eq 1 && ( $1 == --help || $1 == -h ) ]]; then
  cat <<'HELP'
DAO 一键诊断：主站和 Worker VPS 使用同一条命令。
curl -fsSL https://raw.githubusercontent.com/aIlenwang/DAO-install/main/diagnose.sh | sudo bash
自动识别 /opt/dao/dao 与 /opt/dao-worker/dao-worker；兼容 rc.3 起的离线导出。
默认只在本机打包；追加 --upload 上传到私有 aIlenwang/DAO-diagnostics。
--repo owner/repo 指定其他私有仓库；--token-file PATH 指定 root-only 写入授权文件。
也可配置 /etc/dao-diagnostics/github-token；未配置时隐藏询问 Token，不保存输入。
需要诊断仓库 Contents 读写权限，安装只读 Token 不够；公开脚本不含凭据。
不安装、不重启、不升级。上传后打印诊断编号；失败保留本地包。
默认补充最近 24 小时本地轮转日志、HTTP 审计及应用/代理/数据库 journal。
--hours 1..168 调整范围；每来源最多 20000 行/16 MiB，collection.json 明确记录覆盖及截断。
HELP
  exit 0
fi
upload=0
repo=aIlenwang/DAO-diagnostics
token_file=
hours=24
while (( $# )); do
  case $1 in
    --upload) upload=1; shift ;;
    --hours)
      [[ $# -ge 2 && $2 =~ ^[0-9]{1,3}$ ]] && (( 10#$2 >= 1 && 10#$2 <= 168 )) || { echo '--hours 必须为 1..168。' >&2; exit 1; }
      hours=$((10#$2)); shift 2 ;;
    --repo|--token-file)
      [[ $# -ge 2 && -n $2 && $2 != --* ]] || { echo '上传参数缺少值。' >&2; exit 1; }
      if [[ $1 == --repo ]]; then repo=$2; else token_file=$2; fi
      shift 2 ;;
    *) echo '不支持该参数；查看帮助：bash diagnose.sh --help' >&2; exit 1 ;;
  esac
done
if (( ! upload )) && [[ -n $token_file || $repo != aIlenwang/DAO-diagnostics ]]; then
  echo '--repo 和 --token-file 需要配合 --upload。' >&2
  exit 1
fi
[[ $EUID -eq 0 ]] || { echo '请使用 sudo bash 或 root 运行，以读取服务日志。' >&2; exit 1; }
[[ $(uname -s) == Linux ]] || { echo '仅支持 Linux。' >&2; exit 1; }
for cmd in mktemp mkdir timeout tar chmod date; do
  command -v "$cmd" >/dev/null || { echo "缺少命令：$cmd；未执行收集。" >&2; exit 1; }
done
if [[ ! -x /opt/dao/dao && ! -x /opt/dao-worker/dao-worker ]]; then
  echo '未找到一键安装的 DAO 主站或 Worker；请在对应 VPS 上运行。' >&2
  exit 1
fi

umask 077
work=$(mktemp -d /tmp/dao-check.XXXXXX)
contents=$work/contents
mkdir "$contents"
trap 'printf "诊断打包未完成；已收集的信息保留在：%s\n" "$work" >&2' ERR

status() {
  local label=$1
  shift
  printf '\n[%s]\n' "$label"
  if timeout -k 2s 15s "$@" </dev/null; then
    :
  else
    printf '未能完整读取此项（退出码 %s），不代表其他项目失败。\n' "$?"
  fi
}
{
  status time date -Is
  status system uname -srmo
  status uptime uptime
  status memory free -h
  status disk df -h / /var/lib /tmp
  status services systemctl show dao dao-worker dao-https postgresql \
    -p Id -p LoadState -p ActiveState -p SubState -p Result \
    -p NRestarts -p ExecMainStatus -p ActiveEnterTimestamp \
    -p MainPID -p MemoryCurrent -p TasksCurrent
  status database-services systemctl list-units --all --type=service \
    --no-pager --plain --no-legend 'postgresql@*.service'
} >"$contents/status.txt" 2>&1

failures=0
roles=
export_logs() {
  local role=$1
  shift
  printf '正在收集 %s 的近期日志……\n' "$role"
  if timeout -k 2s 30s "$@" -diagnostics "$contents/$role.zip" \
      </dev/null >"$contents/$role-export.txt" 2>&1; then
    if [[ -s $contents/$role.zip ]]; then
      return
    fi
    printf '程序未生成诊断包。\n' >>"$contents/$role-export.txt"
  fi
  failures=$((failures + 1))
  printf '%s 日志导出未完成，错误记录将随状态信息一起打包。\n' "$role"
}
if [[ -x /opt/dao/dao ]]; then
  roles=main
  export_logs main /opt/dao/dao -data /var/lib/dao/data
fi
if [[ -x /opt/dao-worker/dao-worker ]]; then
  roles=${roles:+$roles-}worker
  export_logs worker /opt/dao-worker/dao-worker -config /etc/dao-worker/config.json
fi

if command -v python3 >/dev/null; then
  if ! python3 - "$contents" "$roles" "$hours" <<'DAO_DIAGNOSTIC_COLLECT_PYTHON'
"""Bounded, read-only diagnostic supplement; works with already installed rc.3.

Only whitelisted log files/journal fields are copied. Never dumps environment,
command lines, databases, task files or the contents of Worker configuration.
"""
import datetime as dt
import json
import os
from pathlib import Path
import re
import stat
import subprocess
import sys
import tempfile

MAX_BYTES = 16 << 20
MAX_LINES = 20000
JOURNAL_TIMEOUT = 15
MAX_DATABASE_UNITS = 16
SECRETS = [
    re.compile(r"(?s)-----BEGIN [A-Z ]*PRIVATE KEY-----.*?-----END [A-Z ]*PRIVATE KEY-----"),
    re.compile(r"(?i)\b(?:Bearer|Basic)\s+[a-z0-9._~+/=-]+"),
    re.compile(r"\b(?:github_pat_|gh[pousr]_|sk-)[A-Za-z0-9_-]{12,}"),
    re.compile(r"\beyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+"),
]
PAIR = re.compile(r'''(?i)(["']?(?:api[-_]?key|access[-_]?token|refresh[-_]?token|token|password|passwd|secret|authorization|cookie|set-cookie|database_dsn|dsn|private_key)["']?\s*[:=]\s*)("(?:\\.|[^"\\])*"|'[^']*'|[^\s,;&]+)''')

def redact(value):
    if isinstance(value, dict):
        return {k: ("[REDACTED]" if re.fullmatch(r"(?i)(password|token|authorization|cookie|set-cookie|api_key|database_dsn|secret)", k) else redact(v)) for k,v in value.items()}
    if isinstance(value, list):
        return [redact(v) for v in value]
    if not isinstance(value, str):
        return value
    value = re.sub(r"([a-zA-Z][a-zA-Z0-9+.-]*://)[^\s/@]+@", r"\1[REDACTED]@", value)
    for pattern in SECRETS:
        value = pattern.sub("[REDACTED]", value)
    value = PAIR.sub(r'\1"[REDACTED]"', value)
    # Journal messages may contain Caddy request URIs. Queries can carry a JWT.
    value = re.sub(r"((?:https?://[^\s\"']+|/api/[^\s\"'?]+))\?[^\s\"']*", r"\1?[QUERY REMOVED]", value)
    return value[:8192] + (" [truncated]" if len(value)>8192 else "")

def parse_time(value):
    try:
        parsed = dt.datetime.fromisoformat(value.replace("Z", "+00:00"))
        return parsed.astimezone(dt.timezone.utc) if parsed.tzinfo else None
    except (ValueError, TypeError, AttributeError):
        return None

def regular_open(path, root):
    # Anchor directory traversal to descriptors: no symlink escape or FIFO wait,
    # including a directory replaced while the root collector is reading it.
    parts=path.relative_to(root).parts
    if not parts or any(p in ("..", ".") for p in parts): raise ValueError("invalid log path")
    directory=os.open(root.resolve(),os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW)
    try:
        for part in parts[:-1]:
            child=os.open(part,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW,dir_fd=directory)
            os.close(directory);directory=child
        fd = os.open(parts[-1], os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK,dir_fd=directory)
    finally: os.close(directory)
    if not stat.S_ISREG(os.fstat(fd).st_mode):
        os.close(fd)
        raise ValueError("not a regular log file")
    return os.fdopen(fd,"rb")

def collect_files(root, relative, since, output):
    root = Path(root)
    report = {"source":relative,"files":[],"lines":0,"bytes_read":0,"invalid_lines":0,"truncated":False,"issues":[]}
    selected = []
    budget = MAX_BYTES
    # Newest files have priority under a byte budget; output is chronological.
    for suffix in ("", ".1", ".2", ".3"):
        path = root / relative / ("system.jsonl"+suffix)
        try:
            with regular_open(path,root) as f:
                size = os.fstat(f.fileno()).st_size
                n = min(size,budget)
                offset = size-n
                f.seek(offset)
                data = f.read(n)
                report["files"].append({"name":path.name,"size":size,"bytes_read":len(data)})
                report["bytes_read"] += len(data)
                budget -= len(data)
                report["truncated"] |= offset>0
                if offset: data = data.partition(b"\n")[2]
                lines = data.split(b"\n")[:-1]  # omit concurrent partial write
                rows=[]
                for raw in lines:
                    try: row=json.loads(raw)
                    except (ValueError, UnicodeError): report["invalid_lines"]+=1;continue
                    if not isinstance(row,dict): report["invalid_lines"]+=1;continue
                    at=parse_time(row.get("ts"))
                    if at is not None and at<since: continue
                    # Original log schema only; no arbitrary JSON objects.
                    if "text" in row:
                        row={k:row[k] for k in ("ts","instance","seq","db_id","level","tag","text") if k in row}
                    else:
                        row={k:row[k] for k in ("ts","event","level","request_id","method","route","status","code","client_ip","user_agent","task_id","node_id","elapsed_ms","count","first_at") if k in row}
                    rows.append(redact(row))
                selected=rows+selected
                if len(selected)>MAX_LINES:
                    selected=selected[-MAX_LINES:];report["truncated"]=True
        except FileNotFoundError:
            continue
        except (OSError,ValueError) as error:
            report["issues"].append(redact(str(error)))
    with open(output,"w",encoding="utf-8") as f:
        for row in selected: f.write(json.dumps(row,ensure_ascii=False)+"\n")
    report["lines"]=len(selected)
    report["first_at"]=selected[0].get("ts") if selected else None
    report["last_at"]=selected[-1].get("ts") if selected else None
    report["available"]=bool(report["files"])
    return report

def database_units(status_path):
    # The shell entrypoint already enumerated loaded (including failed/inactive)
    # database units. Reuse that bounded snapshot, not journalctl's glob search
    # over all historical unit names, which can exhaust the timeout on a VPS.
    units={"postgresql.service"}
    issues=[]
    try:
        with regular_open(status_path,status_path.parent) as f:
            data=f.read((64 << 10)+1)
        if len(data)>64 << 10: raise ValueError("service status exceeds read limit")
        section=False;found=False
        for line in data.decode("utf-8",errors="replace").splitlines():
            if line.startswith("["):
                section=line=="[database-services]";found |= section
                continue
            if not section or not line.strip(): continue
            name=line.split()[0]
            if re.fullmatch(r"postgresql@[A-Za-z0-9_.\\:-]+\.service",name):
                if name not in units and len(units)>=MAX_DATABASE_UNITS:
                    issues.append("database unit limit reached; some clusters were not collected")
                    break
                units.add(name)
            else:
                issues.append("database unit enumeration incomplete; see status.txt")
        if not found: issues.append("database service status section unavailable")
    except (OSError,ValueError) as error:
        issues.append("database unit enumeration unavailable: "+redact(str(error)))
    return sorted(units),list(dict.fromkeys(issues))

def collect_journal(unit, since, output):
    units=[unit] if isinstance(unit,str) else list(unit)
    if not units or any(any(c in name for c in "*?[") for name in units):
        raise ValueError("journal collection requires explicit unit names")
    report={"units":units,"lines":0,"truncated":False,"issues":[]}
    if isinstance(unit,str): report["unit"]=unit
    # Limit the child output as well as the final file: no unbounded PIPE read.
    # JSON field whitelist excludes _CMDLINE, environment and arbitrary fields.
    import resource
    def limits(): resource.setrlimit(resource.RLIMIT_FSIZE,(MAX_BYTES,MAX_BYTES))
    with tempfile.TemporaryFile() as raw:
        try:
            args=["journalctl"]
            for name in units: args.extend(["--unit",name])
            args.extend(["--since",since.isoformat(),"--lines",str(MAX_LINES),"--no-pager","--output=json","--output-fields=__REALTIME_TIMESTAMP,MESSAGE,PRIORITY"])
            p=subprocess.run(args,stdout=raw,stderr=subprocess.DEVNULL,timeout=JOURNAL_TIMEOUT,preexec_fn=limits)
            if p.returncode: report["issues"].append("journalctl exit "+str(p.returncode))
        except (OSError,subprocess.TimeoutExpired) as error: report["issues"].append(redact(str(error)))
        size=raw.tell();report["truncated"]=size>=MAX_BYTES
        raw.seek(0)
        with open(output,"w",encoding="utf-8") as f:
            for line in raw:
                try:
                    row=json.loads(line)
                    at=dt.datetime.fromtimestamp(int(row["__REALTIME_TIMESTAMP"])/1000000,dt.timezone.utc).isoformat()
                    message=row.get("MESSAGE","")
                    if not isinstance(message,str): continue
                    # Caddy runtime JSON may include a nested request with headers.
                    # Keep only fields useful for TLS/proxy/connection diagnosis.
                    if message.startswith("{"):
                        try:
                            obj=json.loads(message)
                            message=json.dumps({k:obj[k] for k in ("level","ts","logger","msg","error","duration","status","err_id","err_trace") if k in obj},ensure_ascii=False)
                        except ValueError: pass
                    record={"ts":at,"priority":row.get("PRIORITY"),"text":redact(message)}
                    f.write(json.dumps(record,ensure_ascii=False)+"\n")
                    report["lines"]+=1
                    report.setdefault("first_at",at);report["last_at"]=at
                except (ValueError,TypeError,KeyError,OverflowError): continue
    report["truncated"] |= report["lines"]>=MAX_LINES
    return report

def main(contents, roles, hours):
    contents=Path(contents)
    now=dt.datetime.now(dt.timezone.utc);since=now-dt.timedelta(hours=hours)
    report={"collected_at":now.isoformat(),"since":since.isoformat(),"max_lines_per_source":MAX_LINES,"max_bytes_per_source":MAX_BYTES,"sources":{},"issues":[]}
    units=[]
    for role in roles.split("-"):
        root=Path("/var/lib/dao/data")
        if role=="worker":
            try:
                with regular_open(Path("/etc/dao-worker/config.json"),Path("/etc/dao-worker")) as f:
                    cfg=json.loads(f.read(1<<20))
                root=Path(cfg["data_dir"])
                if not root.is_absolute():raise ValueError("worker data_dir must be absolute")
            except (OSError,ValueError,KeyError) as error:
                report["issues"].append("worker path unavailable: "+redact(str(error)));continue
        for name,relative in (("system","diagnostics"),("http","diagnostics/http")):
            key=role+"-"+name
            report["sources"][key]=collect_files(root,relative,since,contents/(key+".jsonl"))
        units.extend(["dao", "dao-https"] if role=="main" else ["dao-worker"])
    # Database startup/error logs and optional domain-based Caddy use only unit journals.
    units.append("caddy")
    for unit in units:
        key="journal-"+unit.replace("*","clusters")
        report["sources"][key]=collect_journal(unit,since,contents/(key+".jsonl"))
    db_units,db_issues=database_units(contents/"status.txt")
    key="journal-postgresql@clusters"
    report["sources"][key]=collect_journal(db_units,since,contents/(key+".jsonl"))
    report["sources"][key]["issues"].extend(db_issues)
    report["partial"]=bool(report["issues"]) or any(x.get("issues") or x.get("truncated") or x.get("invalid_lines") for x in report["sources"].values())
    (contents/"collection.json").write_text(json.dumps(report,ensure_ascii=False,indent=2)+"\n")
    total=sum(x.get("lines",0) for x in report["sources"].values())
    print(f"补充采集最近 {hours} 小时：{total} 条记录；各来源行数、时间范围和截断情况见 collection.json。")
    if report["partial"]:print("部分来源读取失败或达到限额，已明确记录；原始日志未修改。")

if __name__=="__main__":
    main(sys.argv[1],sys.argv[2],int(sys.argv[3]))
DAO_DIAGNOSTIC_COLLECT_PYTHON
  then
    printf '补充采集异常，原生诊断包已保留。\n'
    printf 'supplement collection failed\n' >"$contents/collection-error.txt"
    failures=$((failures + 1))
  fi
else
  printf 'python3 unavailable; extended logs not collected\n' >"$contents/collection-error.txt"
  failures=$((failures + 1))
fi

cat >"$contents/README.txt" <<'INFO'
DAO 按需诊断包：status.txt 为采集时的操作系统/服务状态；main.zip、worker.zip
使用已安装程序的离线导出，包含程序版本、近期本地日志和对应 systemd journal。
额外的 main/worker-system.jsonl、*-http.jsonl 和 journal-*.jsonl 不受旧版 200 行限制。
默认最近 24 小时，可用 --hours 调整；collection.json 列明各来源范围、条数、读取失败和截断。
系统文件与 journal 可能记录同一事件，分析时不要重复计数。缺少 http 文件在 rc.3 为正常情况。
不声称收集数据库中的全部历史，轮转前已删除的记录不能恢复；任何限额都在清单中标明。
缺少某角色表示本机未安装该角色；*-export.txt 记录导出结果，失败时保留部分信息。
诊断 ZIP 中 partial/issues 说明缺失项。服务不存在或当前系统不支持某命令，也会记录。
不含完整配置、密码文件、数据库备份、任务目录或全量模型/工具录制。
常见日志凭据由 DAO 脱敏；业务内容和未标注的秘密仍需在分享前检查。
离线导出不连接数据库或主站，不能仅凭本包证明每个任务、模型和 MCP 都正常。
脚本不安装软件、不更改服务、不升级；只有显式 --upload 才上传到私有 GitHub。
上传凭据不进入本包，原始应用日志保持不变；上传回执另存于包旁 upload-receipt.json。
INFO

archive=$work/dao-diagnostics.tar.gz
tar -czf "$archive" -C "$contents" .
chmod 600 "$archive"
trap - ERR
if (( failures > 0 )); then
  printf '\n已生成部分诊断包（%s 个角色导出异常）。\n' "$failures"
else
  printf '\n诊断包已生成。\n'
fi
if (( upload )); then
  printf '本地诊断备份：%s\n' "$archive"
  command -v python3 >/dev/null || { echo '上传需要 python3；本地诊断包已保留。' >&2; exit 1; }
  python3 - "$archive" "$repo" "$token_file" "$roles" <<'DAO_DIAGNOSTIC_UPLOAD_PYTHON'
"""Upload an explicitly requested diagnostic bundle to a private GitHub release."""
import datetime
import getpass
import hashlib
import json
import os
from pathlib import Path
import re
import secrets
import socket
import stat
import sys
import tempfile
import urllib.error
import urllib.parse
import urllib.request
import warnings

MAX_BUNDLE = 16 << 20
DEFAULT_REPO = "aIlenwang/DAO-diagnostics"


class UploadError(Exception):
    def __init__(self, message, status=0):
        super().__init__(message)
        self.status = status


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


class GitHub:
    def __init__(self, token):
        self.token = token
        self.http = urllib.request.build_opener(NoRedirect())

    def request(self, method, url, value=None, binary=False):
        parts = urllib.parse.urlsplit(url)
        if parts.scheme != "https" or parts.netloc not in ("api.github.com", "uploads.github.com"):
            raise UploadError("拒绝向非 GitHub API 地址发送授权。")
        body = value if binary else json.dumps(value).encode() if value is not None else None
        request = urllib.request.Request(url, data=body, method=method, headers={
            "Accept": "application/vnd.github+json",
            "X-GitHub-Api-Version": "2022-11-28",
            "User-Agent": "DAO-diagnostics",
            "Content-Type": "application/gzip" if binary else "application/json",
        })
        request.add_unredirected_header("Authorization", "Bearer " + self.token)
        try:
            with self.http.open(request, timeout=60) as response:
                data = response.read((2 << 20) + 1)
            if len(data) > 2 << 20:
                raise UploadError("GitHub 返回超出大小限制的响应。")
            return json.loads(data)
        except urllib.error.HTTPError as error:
            if error.code in (401, 403):
                message = "GitHub 授权不足或受到限流：需要诊断仓库 Contents 读写权限，安装只读 Token 不够。"
            elif error.code == 404:
                message = "找不到私有诊断仓库/资源，或当前 Token 没有访问权限。"
            else:
                message = "GitHub 请求失败（HTTP %s），本地诊断包已保留。" % error.code
            raise UploadError(message, error.code) from None
        except (OSError, ValueError) as error:
            # Remote response bodies and exception strings can contain credentials.
            raise UploadError("GitHub 网络或响应异常，本地诊断包已保留。") from None


def read_token(path):
    if path:
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        with os.fdopen(fd) as stream:
            info = os.fstat(stream.fileno())
            if not stat.S_ISREG(info.st_mode) or info.st_uid != 0 or info.st_mode & 0o077:
                raise UploadError("Token 文件必须属于 root，且其他用户不可读写（建议权限 0600）。")
            token = stream.read(8193).strip()
    else:
        # Fail instead of falling back to echoed stdin when run through curl/cron.
        with warnings.catch_warnings():
            warnings.simplefilter("error", getpass.GetPassWarning)
            try:
                # getpass opens the controlling TTY using unbuffered FileIO.
                # open('/dev/tty', 'w+') requires seeking and fails even on an
                # interactive SSH terminal; stdin may also be the script pipe.
                token = getpass.getpass("诊断仓库 GitHub 写入 Token（隐藏输入，不保存）：").strip()
            except (OSError, getpass.GetPassWarning, EOFError):
                raise UploadError("无法隐藏输入 Token；请使用 --token-file 指定 root-only 的诊断授权文件。") from None
    if not token or len(token) > 8192 or any(c.isspace() for c in token) or not token.isascii():
        raise UploadError("GitHub Token 格式无效。")
    return token


def save_receipt(path, value):
    fd, temporary = tempfile.mkstemp(prefix=".receipt-", dir=path.parent)
    try:
        with os.fdopen(fd, "w") as stream:
            json.dump(value, stream, ensure_ascii=False, indent=2)
        os.replace(temporary, path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


def verify_asset(asset, name, size, digest):
    if (not isinstance(asset, dict) or not isinstance(asset.get("id"), int) or asset["id"] <= 0
            or asset.get("name") != name or asset.get("state") != "uploaded"
            or asset.get("size") != size or asset.get("digest") != "sha256:" + digest):
        raise UploadError("远端文件尚未通过大小和 SHA-256 核验，未标记上传成功。")


def upload(archive, repo, token, roles, client=None):
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9-]{0,38}/[A-Za-z0-9_.-]{1,100}", repo):
        raise UploadError("诊断仓库必须为 owner/repository。")
    if roles not in ("main", "worker", "main-worker"):
        raise UploadError("诊断角色无效。")
    with archive.open("rb") as stream:
        if not stat.S_ISREG(os.fstat(stream.fileno()).st_mode):
            raise UploadError("诊断包不是普通文件。")
        data = stream.read(MAX_BUNDLE + 1)
    if not data or len(data) > MAX_BUNDLE:
        raise UploadError("诊断包为空或超过 16 MiB，未上传。")
    client = client or GitHub(token)
    base = "https://api.github.com/repos/" + repo
    identity = client.request("GET", base)
    if (not isinstance(identity, dict) or identity.get("private") is not True
            or str(identity.get("full_name", "")).lower() != repo.lower()):
        raise UploadError("目标不是指定的私有仓库，拒绝上传诊断日志。")

    now = datetime.datetime.now(datetime.timezone.utc)
    tag = "diagnostics-" + now.strftime("%Y-%m-%d")
    host = re.sub(r"[^A-Za-z0-9.-]", "-", socket.gethostname())[:48] or "host"
    reference = roles + "-" + host + "-" + now.strftime("%Y%m%dT%H%M%SZ") + "-" + secrets.token_hex(4)
    name = "dao-" + reference + ".tar.gz"
    digest = hashlib.sha256(data).hexdigest()
    receipt_path = archive.parent / "upload-receipt.json"
    receipt = {"id": reference, "repository": repo, "tag": tag, "asset": name,
               "bytes": len(data), "sha256": digest, "state": "pending"}
    save_receipt(receipt_path, receipt)
    release_url = base + "/releases/tags/" + tag
    try:
        release = client.request("GET", release_url)
    except UploadError as error:
        if error.status != 404:
            raise
        try:
            release = client.request("POST", base + "/releases", {
                "tag_name": tag, "name": "DAO diagnostics " + now.strftime("%Y-%m-%d") + " (UTC)",
                "body": "On-demand private diagnostic bundles; not application releases.",
                "draft": False, "prerelease": True, "make_latest": "false",
            })
        except UploadError as error:
            if error.status != 422:
                raise
            release = client.request("GET", release_url)  # Another VPS created today's release.
    release_id = release.get("id") if isinstance(release, dict) else None
    if not isinstance(release_id, int) or release_id <= 0 or release.get("tag_name") != tag:
        raise UploadError("诊断发行记录身份无效。")
    url = "https://uploads.github.com/repos/" + repo + "/releases/%d/assets?" % release_id + urllib.parse.urlencode({"name": name})
    try:
        asset = client.request("POST", url, data, binary=True)
    except UploadError as error:
        if error.status not in (0, 408, 409, 422, 500, 502, 503, 504):
            raise
        # A lost upload response is not proof of failure. Reconcile by unique ID
        # and digest; never overwrite or blindly send the same bundle again.
        asset = None
        for page in range(1, 11):
            assets = client.request("GET", base + "/releases/%d/assets?per_page=100&page=%d" % (release_id, page))
            if not isinstance(assets, list):
                raise UploadError("无法核查上传结果。")
            asset = next((a for a in assets if isinstance(a, dict) and a.get("name") == name), None)
            if asset or len(assets) < 100:
                break
        if asset is None:
            raise UploadError("无法确认上传结果；已保留本地包及编号，请检查私有仓库。") from None
    verify_asset(asset, name, len(data), digest)
    receipt.update(state="uploaded", asset_id=asset.get("id"),
                   url="https://github.com/" + repo + "/releases/tag/" + tag)
    save_receipt(receipt_path, receipt)
    return receipt


def main():
    token = ""
    try:
        archive, repo, token_file, roles = sys.argv[1:]
        if not token_file and Path("/etc/dao-diagnostics/github-token").exists():
            token_file = "/etc/dao-diagnostics/github-token"
        token = read_token(token_file)
        receipt = upload(Path(archive), repo, token, roles)
        print("上传已核验，诊断编号：" + receipt["id"])
        print("私有诊断位置：" + receipt["url"])
        print("把这个编号告诉维护者即可，无需下载再上传诊断包。")
        return 0
    except UploadError as error:
        print(str(error), file=sys.stderr)
    except (OSError, ValueError):
        print("读取上传参数、授权或文件失败；本地诊断包已保留。", file=sys.stderr)
    finally:
        token = ""
    return 1


if __name__ == "__main__":
    raise SystemExit(main())
DAO_DIAGNOSTIC_UPLOAD_PYTHON
else
  printf '请下载并发送这个文件：%s\n' "$archive"
fi
